 stream(){if(!run)return;const cx=Math.floor(run.player.x/256),cy=Math.floor(run.player.y/256);if(cx===this.cx&&cy===this.cy)return;this.cx=cx;this.cy=cy;props.clear();for(let yy=cy-3;yy<=cy+3;yy++)for(let xx=cx-2;xx<=cx+2;xx++)for(let j=0;j<2;j++){const h=hash(xx,yy,this.seed+j*3527),key=xx+','+yy+','+j;if(this.broken.has(key))continue;const p=props.get();if(!p)return;p.x=xx*256+24+(h%208);p.y=yy*256+24+((h>>>9)%208);p.key=key;p.type=['grave','tree','bones','urn','torch','pillar'][h%6];p.hp=p.type==='urn'?18:1e9;p.size=p.type==='urn'?18:0;}},
 damageProp(p,damage){if(!p||p.type!=='urn'||p.hp<=0)return;p.hp-=damage;if(p.hp>0)return;this.broken.add(p.key);if(this.broken.size>2048)this.broken.delete(this.broken.values().next().value);Terrain.invalidate();burst(p.x,p.y,'#9b7952',9);const n=Math.random();drop(p.x,p.y,n<.22?'health':n<.7?'gold':'xp',n<.7?8:15);for(let i=0;i<props.count;i++)if(props.items[i]===p){props.remove(i);break;}},
