function number(x,y,value,color='#d9cfb8',big=false){if(!save.settings.numbers)return;const n=numbers.get();if(!n)return;n.x=x;n.y=y;n.value=typeof value==='number'?displayNumber(value):String(value);n.color=color;n.life=.7;n.max=.7;n.big=big;n.vx=rand(-12,12);}
