function drop(x,y,type='xp',value=1){if(drops.count>760&&type==='xp'){let nearest=null,dd=1e12;for(let i=0;i<drops.count;i++){const a=drops.items[i],d=(a.x-x)**2+(a.y-y)**2;if(a.type==='xp'&&d<dd){nearest=a;dd=d;}}if(nearest){nearest.value+=value;return nearest;}}const a=drops.get();if(!a)return null;a.x=x;a.y=y;a.type=type;a.value=value;a.age=0;a.pull=false;a.seed=rand(0,TAU);return a;}
/** Recompute derived stats only when equipment changes. */
function statsV1(){run.statsRevision=(run.statsRevision||0)+1;const p=run.player,old=p.maxHp||100,h=selectedHero;const s={maxHp:100*(1+metaLv('health')*.08),regen:.2,speed:140*(1+metaLv('speed')*.05),armor:metaLv('armor')+(h===0?2:0),might:1+metaLv('might')*.05,area:1,cooldown:metaLv('cooldown')*.03,projectile:1,duration:1,amount:metaLv('amount'),magnet:70+metaLv('magnet')*15,luck:metaLv('luck')*.05,crit:.05,critMult:2,revives:metaLv('reviveStat'),growth:1+metaLv('growth')*.06,greed:1+metaLv('greed')*.08,curse:curseChoice+metaLv('curseStat')*.1};
 for(let i=0;i<16;i++){const n=run.passives[i]||0;if(!n)continue;const d=PASSIVES[i],v=d.value*n;if(d.stat==='health')s.maxHp+=100*v;else if(d.stat==='speed')s.speed+=140*v;else s[d.stat]+=v;}if(h===1){s.speed*=1.15;s.crit+=.1;}if(h===2){s.area+=.25;s.maxHp*=.8;}if(h===3)s.amount++;if(h===4){s.regen++;s.duration+=.25;}s.cooldown=clamp(s.cooldown,0,.6);s.crit=clamp(s.crit,0,.85);Object.assign(p,s);p.hp=clamp((p.hp||old)+(s.maxHp-old),0,s.maxHp);}
function startRunV1(){for(const p of [enemies,shots,drops,particles,numbers,effects,allies])p.clear();selectedStage=clamp(selectedStage,0,47);run={time:0,kills:0,gold:0,soulstones:0,level:1,xp:0,nextXP:xpToNext(1),weapons:[{id:HEROES[selectedHero].weapon,level:1,evolved:false,cd:.3}],passives:new Uint8Array(16),banished:new Set(),rerolls:1+metaLv('rerolls'),banishes:1+metaLv('banishes'),pending:0,spawn:.7,events:0,swarm90:false,bosses:0,finalDefeated:false,reaper:false,skillCD:0,dashCD:0,revived:0,ended:false,slowmo:0,chestTier:1,chestRewards:[],merge:0,player:{x:0,y:0,hp:100,maxHp:100,facing:1,aim:0,vx:0,vy:0,invuln:1,dash:0,walk:0,skillBuff:0},cam:{x:0,y:0},stage:selectedStage,seed:Math.floor(rand(1,1e8)),startKills:save.kills};stats();run.player.hp=run.player.maxHp;world.reset(run.seed);world.stream();state='RUN';hideUI();Input.reset();hitStop=0;trauma=0;quality=save.settings.quality==='auto'?'medium':save.settings.quality;qualityMeasure.time=0;qualityMeasure.sum=0;qualityMeasure.n=0;try{history.pushState({hellbound:true},'');}catch(_){}requestWake();if(!save.tutorialSeen){toast(T('tutorial'));save.tutorialSeen=true;persist();}}
function spawnEnemyV1(id=0,elite=false,x=null,y=null,boss=-1){if(!run)return null;if(enemies.count>=caps()&&boss<0)return null;if(enemies.count===enemies.cap)return null;const e=enemies.get(),d=boss>=0?BOSSES[boss]:id===99?{sprite:'reaper',hp:1e12,speed:140,damage:9999,size:30}:ENEMIES[id],p=run.player;if(x===null){const a=rand(0,TAU),r=590;x=p.x+Math.cos(a)*r;y=p.y+Math.sin(a)*r;}const scaling=(1+.08*run.time/60)*p.curse*(1+run.stage*.075);e.uid=++uniqueId;e.id=id;e.boss=boss;e.elite=elite;e.sprite=d.sprite;e.x=x;e.y=y;e.maxHp=d.hp*scaling*(elite?6:1);e.hp=e.maxHp;e.speed=d.speed*(elite?1.13:1);e.damage=d.damage*(elite?1.6:1);e.r=d.size*(elite?1.18:1);e.xp=boss>=0?120:elite?50:d.xp||0;e.resist=d.resist||0;e.behavior=boss>=0?'boss':id===99?'reaper':d.behavior;e.age=rand(0,6);e.walk=rand(0,8);e.moveSpeed=0;e.drawAngle=0;e.flash=0;e.slow=0;e.slowFactor=1;e.cd=rand(1.5,3);e.action=0;e.tx=0;e.ty=0;e.vx=0;e.vy=0;e.orbitHit=0;e.mod1=elite?Math.floor(rand(0,8)):-1;e.mod2=elite?Math.floor(rand(0,8)):-1;e.dead=false;e.poisonTime=0;e.poisonTick=0;e.poisonDamage=0;e.novaStamp=-1;e.phase=0;e.phaseTimer=0;e.trail=.6;e.charging=0;if(e.mod1===0||e.mod2===0)e.speed*=1.5;if(e.mod1===4||e.mod2===4)e.damage*=1.5;if(e.mod1===6||e.mod2===6)e.resist+=.25;if(boss>=0){run.bosses++;e.cd=2.5;Sound.play('boss');vibrate(70);showBossIntro(e);}return e;}
function nearest(x,y,range=900){let target=null,d=range*range;for(let i=0;i<enemies.count;i++){const e=enemies.items[i];if(e.hp<=0)continue;const dd=(e.x-x)**2+(e.y-y)**2;if(dd<d&&Terrain.clear(x,y,e.x,e.y)){d=dd;target=e;}}return target;}
function hit(e,damage,crit=true,knock=0,source=-1,ox=run.player.x,oy=run.player.y){if(!e||e.hp<=0||e.id===99)return;if(ox!==null&&!Terrain.clear(ox,oy,e.x,e.y))return;if(e.behavior==='phase'&&Math.sin(e.age*2.1)<-.25)return;const p=run.player,c=crit&&Math.random()<p.crit,melee=source===0||source===8||source===11;let v=damage*p.might*(c?p.critMult:1)*(1-clamp(e.resist,0,.8))*(selectedHero===0&&melee?1.2:1)*(p.buffPower>0?1.25:1);if(e.behavior==='boss')v*=1;e.hp-=v;e.flash=.1;number(e.x+rand(-7,7),e.y-e.r,Math.round(v),c?PAL.GOLD_BRIGHT:PAL.BONE,c);if(knock&&e.boss<0){const a=Math.atan2(e.y-p.y,e.x-p.x);Terrain.move(e,e.x+Math.cos(a)*knock,e.y+Math.sin(a)*knock,e.r);}if(c&&frameNo%4===0)Sound.play('crit');if(e.hp<=0){e.dead=true;if(source===11)heal(1);if(selectedHero===3&&Math.random()<.05)raiseAlly(e.x,e.y);}}
function areaHit(x,y,r,damage,source=-1,slow=0,ox=x,oy=y){grid.query(x,y,r+50);for(let j=0;j<grid.count;j++){const e=enemies.items[grid.result[j]];if(e.hp>0&&(e.x-x)**2+(e.y-y)**2<(r+e.r)**2&&Terrain.clear(x,y,e.x,e.y)&&Terrain.clear(ox,oy,e.x,e.y)){hit(e,damage,true,source===6?8:0,source,x,y);if(slow){e.slow=Math.max(e.slow,slow);e.slowFactor=.42;}}}world.breakUrns(x,y,r,damage);}
function hurtV1(damage,source=null){const p=run.player;if(p.invuln>0||run.ended||state!=='RUN')return;const n=Math.max(1,damage-p.armor);p.hp-=n;p.invuln=.5;trauma=clamp(trauma+.35,0,1);number(p.x,p.y-30,Math.ceil(n),PAL.BLOOD_BRIGHT,true);Sound.play('hurt');vibrate(20);if(source&&(source.mod1===5||source.mod2===5||source.boss===1))source.hp=Math.min(source.maxHp,source.hp+n*3);if(p.hp<=0){if(run.revived<p.revives){run.revived++;p.hp=p.maxHp*.65;p.invuln=3;effect('ring',p.x,p.y,200,PAL.GOLD_BRIGHT,.8);areaHit(p.x,p.y,200,80);toast(T('revive'));Sound.play('level');}else finishRun(false);}}
function heal(v){if(!run)return;const p=run.player,old=p.hp;p.hp=Math.min(p.maxHp,p.hp+v);if(p.hp-old>=3)number(p.x,p.y-26,'+'+Math.round(p.hp-old),'#8ca55c');}
