function availableChoices(){const a=[];for(const d of WEAPONS){const w=run.weapons.find(w=>w.id===d.id);if(run.banished.has('w'+d.id)||w&&(w.level>=8||w.evolved)||!w&&run.weapons.length>=6)continue;a.push({type:'w',id:d.id,weight:w?4:3-d.rarity*.6});}let count=0;for(const n of run.passives)if(n)count++;for(const d of PASSIVES){if(run.banished.has('p'+d.id)||run.passives[d.id]>=5||!run.passives[d.id]&&count>=6)continue;a.push({type:'p',id:d.id,weight:run.passives[d.id]?3:2.5});}return a;}
function rollChoices(){const pool=availableChoices(),a=[],n=run.player.luck>=.4?4:3;while(a.length<n&&pool.length){let sum=0;for(const o of pool)sum+=o.weight*(o.type==='w'?1+run.player.luck*.4:1);let r=rand(0,sum),index=0;for(let i=0;i<pool.length;i++){r-=pool[i].weight*(pool[i].type==='w'?1+run.player.luck*.4:1);if(r<=0){index=i;break;}}a.push(pool.splice(index,1)[0]);}if(!a.length)a.push({type:'gold',id:0},{type:'heal',id:0});return a;}
function grant(o){if(o.type==='w'){let w=run.weapons.find(w=>w.id===o.id);if(w)w.level=Math.min(8,w.level+1);else run.weapons.push({id:o.id,level:1,evolved:false,cd:.3});}else if(o.type==='p')run.passives[o.id]=Math.min(5,run.passives[o.id]+1);else if(o.type==='evo'){const w=run.weapons.find(w=>w.id===o.id);if(w)w.evolved=true;}else if(o.type==='gold')run.gold+=40*run.player.greed;else heal(run.player.maxHp*.35);stats();}
function chooseUpgrade(index){const o=choices[index];if(!o||state!=='LEVELUP')return;if(banishMode){run.banished.add(o.type+o.id);run.banishes--;banishMode=false;choices=rollChoices();renderLevelup();return;}grant(o);run.pending--;Sound.play('coin');if(run.pending>0){choices=rollChoices();renderLevelup();}else{state='RUN';hideUI();Input.reset();}}
function openChest(tier){if(run.ended)return;run.chestTier=tier;run.chestRewards=[];const evo=run.weapons.find(w=>w.level===8&&!w.evolved&&run.passives[WEAPONS[w.id].passive]>0);if(evo){const o={type:'evo',id:evo.id};grant(o);run.chestRewards.push(o);}const n=tier===5?5:tier===3?3:1;while(run.chestRewards.length<n){const opts=availableChoices().filter(o=>o.type==='p'?run.passives[o.id]>0:run.weapons.some(w=>w.id===o.id)),o=opts.length?pick(opts):{type:'gold',id:0};grant(o);run.chestRewards.push(o);}state='CHEST';Input.reset();Sound.play('chest');showChest();}
function updateUnlocksV1(){let fresh=false;const add=(a,v)=>{if(!a.includes(v)){a.push(v);fresh=true;}};if(save.maxLevel>=15)add(save.unlockedHeroes,2);if(save.kills>=1000)add(save.unlockedHeroes,3);if(save.wins[0]){add(save.unlockedHeroes,4);add(save.unlockedStages,1);}if(save.wins[1])add(save.unlockedStages,2);for(let i=0;i<ACHIEVEMENTS.length;i++){const a=ACHIEVEMENTS[i],v=a.metric.startsWith('win')?save.wins[Number(a.metric.slice(-1))]:save[a.metric];if(v>=a.goal)add(save.achievements,i);}return fresh;}
function finishRunV1(victory){if(!run||run.ended)return;run.ended=true;run.victory=victory;save.gold+=Math.floor(run.gold);save.soulstones+=run.soulstones;save.kills+=run.kills;save.runs++;save.maxLevel=Math.max(save.maxLevel,run.level);save.best[run.stage]=Math.max(save.best[run.stage],Math.min(900,run.time));if(victory){save.wins[run.stage]++;if(run.stage===1&&run.revived===0&&!save.unlockedHeroes.includes(5))save.unlockedHeroes.push(5);}run.fresh=updateUnlocks();persist();state='RESULT';Input.reset();Sound.play(victory?'level':'boss');showResult();if(!saveAvailable)toast(T('saveWarning'));}


