const dark=surface(270,480),dc=dark.getContext('2d'),vignette=surface(540,960),grain=surface(128,128),sortList=new Array(430);let sortCount=0;const GROUND_FX=new Set(['zone','hostileZone','totem','hostileWarn','chargeWarn','meteor','flameRing']);
function buildOverlays(){const c=vignette.getContext('2d'),g=c.createRadialGradient(270,440,130,270,480,610);g.addColorStop(0,'transparent');g.addColorStop(.6,'rgba(3,2,3,.12)');g.addColorStop(1,'rgba(2,1,2,.88)');c.fillStyle=g;c.fillRect(0,0,540,960);const n=grain.getContext('2d'),r=seeded(825);for(let i=0;i<1500;i++)rect(n,r()*128,r()*128,1,1,r()>.5?'#ffffff14':'#00000024');}
function screenX(x){return x-(run?run.cam.x:0)+270;}function screenY(y){return y-(run?run.cam.y:0)+470;}
function inView(x,y,r=90){const sx=screenX(x),sy=screenY(y);return sx>-r&&sy>-r&&sx<540+r&&sy<960+r;}
function text(s,x,y,size=18,color=PAL.BONE,align='center',bold=false){if(typeof s==='number')s=displayNumber(s);ctx.font=`${bold?'bold ':''}${size}px Georgia,serif`;ctx.textAlign=align;ctx.textBaseline='middle';ctx.lineWidth=3;ctx.strokeStyle='#090708';ctx.strokeText(String(s),x,y);ctx.fillStyle=color;ctx.fillText(String(s),x,y);}
function frame(x,y,w,h,color=PAL.GOLD){ctx.fillStyle='#171314e8';ctx.fillRect(x,y,w,h);ctx.strokeStyle='#4e3927';ctx.lineWidth=3;ctx.strokeRect(x,y,w,h);ctx.lineWidth=1;ctx.strokeStyle=color;ctx.strokeRect(x+3,y+3,w-6,h-6);const l=12;for(const a of [[x,y,1,1],[x+w,y,-1,1],[x,y+h,1,-1],[x+w,y+h,-1,-1]]){line(ctx,a[0]+a[2]*l,a[1]+a[3]*3,a[0]+a[2]*3,a[1]+a[3]*l,color,1);}}
function drawFloorV1(){const cam=run?run.cam:{x:Math.sin(clock*.03)*70,y:clock*5},b=run?run.stage:0,ox=cam.x-270,oy=cam.y-470,tx=Math.floor(ox/128),ty=Math.floor(oy/128);for(let y=ty;y<=ty+8;y++)for(let x=tx;x<=tx+5;x++){const s=floorTiles[b][hash(x,y,run?run.seed:76)%4];ctx.drawImage(s,Math.floor(x*128-ox),Math.floor(y*128-oy));}}
function drawActorV1(id,x,y,size=64,flip=1,bob=0,flash=0,alpha=1){const sx=screenX(x),sy=screenY(y),h=size*1.25;ctx.globalAlpha=alpha;ellipse(ctx,sx,sy+5,size*.3,size*.12,'#00000085');ctx.save();ctx.translate(Math.round(sx),Math.round(sy+bob));ctx.scale(flip,1);ctx.drawImage(getImage(id),-size/2,-h+14,size,h);if(flash>0){ctx.globalAlpha=alpha*.75;ctx.drawImage(whiteSprites[id]||getImage(id),-size/2,-h+14,size,h);}ctx.restore();ctx.globalAlpha=1;}
function drawProps(){for(let i=0;i<props.count;i++){const p=props.items[i];if(!inView(p.x,p.y))continue;const sx=screenX(p.x),sy=screenY(p.y);ellipse(ctx,sx,sy,30,9,'#00000078');ctx.drawImage(getImage(p.type),sx-40,sy-100,80,110);if(p.type==='torch'){ctx.globalCompositeOperation='lighter';ctx.drawImage(glows.fire,sx-25,sy-80,50,50);ctx.globalCompositeOperation='source-over';}}}
function drawDecals(){for(let i=0;i<decals.count;i++){const d=decals.items[i];if(!inView(d.x,d.y,d.size))continue;ctx.save();ctx.translate(screenX(d.x),screenY(d.y));ctx.rotate(d.rotation);ctx.globalAlpha=Math.min(.65,d.life/20);ellipse(ctx,0,0,d.size*1.5,d.size*.8,'#3c0b11');ellipse(ctx,d.size,-d.size*.5,d.size*.35,d.size*.25,'#591018');ctx.restore();}ctx.globalAlpha=1;}
function drawPickups(){for(let i=0;i<drops.count;i++){const d=drops.items[i];if(!inView(d.x,d.y,50))continue;const x=screenX(d.x),y=screenY(d.y)+Math.sin(clock*4+d.seed)*2;if(d.type==='xp'){const color=d.value>30?'#ab4345':d.value>8?'#72a983':'#6da5ce';ctx.drawImage(d.value>8?glows.warm:glows.blue,x-11,y-11,22,22);poly(ctx,[x,y-5,x+4,y,x,y+5,x-4,y],color,null);rect(ctx,x-1,y-3,2,2,'#d5e5dd');}
 else if(d.type==='gold'){ellipse(ctx,x,y,5,4,'#bc9141');line(ctx,x-2,y-2,x+2,y-2,'#efd789',2);}
 else if(d.type==='mana'){ctx.drawImage(glows.blue,x-15,y-15,30,30);poly(ctx,[x-4,y-7,x+4,y-7,x+3,y-2,x+6,y+6,x-6,y+6],'#638fb1','#1c3345');}else if(d.type==='health'){ctx.drawImage(glows.blood,x-19,y-19,38,38);ellipse(ctx,x,y,8,8,'#931f2b');ellipse(ctx,x-2,y-3,3,2,'#e77b71');}
 else if(d.type==='chest'){ctx.globalAlpha=.22+.08*Math.sin(clock*3);rect(ctx,x-13,y-210,26,210,'#ebbc59');ctx.globalAlpha=1;frame(x-16,y-13,32,25,'#d3b05f');rect(ctx,x-14,y-9,28,10,'#705337');rect(ctx,x-2,y-4,5,8,'#e1bd66');}
 else{ctx.drawImage(glows.warm,x-23,y-23,46,46);text(d.type==='magnet'?'✦':'✧',x,y,26,d.type==='magnet'?'#9ec4d7':PAL.GOLD_BRIGHT);}}}
function drawEffectV1(f){if(!inView(f.x,f.y,f.r+70))return;const x=screenX(f.x),y=screenY(f.y),progress=1-f.life/f.max;ctx.save();ctx.strokeStyle=f.color;ctx.fillStyle=f.color;
 switch(f.kind){case 'hostileWarn':case 'meteor':ctx.globalAlpha=.15+progress*.23;ellipse(ctx,x,y,f.r,f.r*.75,f.color);ctx.globalAlpha=.9;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(x,y,f.r,f.r*.75,0,-Math.PI/2,-Math.PI/2+TAU*progress);ctx.stroke();line(ctx,x-7,y-7,x+7,y+7,f.color,2);line(ctx,x+7,y-7,x-7,y+7,f.color,2);break;
 case 'chargeWarn':line(ctx,x,y,screenX(f.tx),screenY(f.ty),'#b32d2d',12);break;
 case 'hostileZone':case 'zone':case 'totem':{ctx.globalAlpha=Math.min(1,f.life)*.22;ellipse(ctx,x,y,f.r,f.r*.75,f.color);ctx.globalAlpha=.7;ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(x,y,f.r*(.82+.04*Math.sin(clock*4)),f.r*.65,0,0,TAU);ctx.stroke();if(f.kind==='totem'){ctx.globalAlpha=.9;ctx.drawImage(icons.w10,x-20,y-40,40,40);}else for(let j=0;j<4;j++)ellipse(ctx,x+Math.sin(j*7+clock)*f.r*.6,y+Math.cos(j*5+clock*.6)*f.r*.45,4,2,f.color);break;}
 case 'flameRing':ctx.lineWidth=15;ctx.globalAlpha=.55;ctx.beginPath();ctx.arc(x,y,f.r,0,TAU);ctx.stroke();break;
 case 'slash':case 'scythe':{ctx.translate(x,y);ctx.rotate(f.kind==='slash'?f.angle:progress*TAU);ctx.globalAlpha=1-progress;const a=f.kind==='slash'?-f.width/2:0,b=f.kind==='slash'?f.width/2:TAU*.85;ctx.lineWidth=6*(1-progress)+1;ctx.beginPath();ctx.arc(0,0,f.r*(.6+progress*.4),a,b);ctx.stroke();ctx.globalAlpha=(1-progress)*.1;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,f.r,a,b);ctx.fill();break;}
 case 'whip':ctx.globalAlpha=1-progress;ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x,y);for(let j=0;j<9;j++)ctx.lineTo(x+Math.cos(f.angle)*f.r*j/8,y+Math.sin(j*1.8-progress*8)*10);ctx.stroke();break;
 case 'bolt':ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(screenX(f.tx),screenY(f.ty)-20);ctx.lineTo(x-14,y-35);ctx.lineTo(x+11,y-27);ctx.lineTo(x,y);ctx.stroke();ctx.drawImage(glows.warm,x-40,y-40,80,80);break;
 case 'frost':case 'ring':ctx.globalAlpha=(1-progress)*.8;ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(x,y,f.r*(.4+.6*progress),f.r*(.4+.6*progress)*.8,0,0,TAU);ctx.stroke();break;
 case 'explosion':ctx.globalAlpha=(1-progress)*.7;ctx.drawImage(glows.fire,x-f.r,y-f.r,f.r*2,f.r*2);ctx.lineWidth=5*(1-progress);ctx.beginPath();ctx.arc(x,y,f.r*progress,0,TAU);ctx.stroke();break;
 case 'ghost':ctx.globalAlpha=(1-progress)*.3;ctx.drawImage(getImage('hero'+selectedHero),x-32,y-66,64,80);break;}
 ctx.restore();}
function drawShotsV1(){for(let i=0;i<shots.count;i++){const s=shots.items[i];if(!inView(s.x,s.y,40))continue;const x=screenX(s.x),y=screenY(s.y);ctx.save();ctx.translate(x,y);ctx.rotate(s.spin?s.angle:Math.atan2(s.vy,s.vx));if(s.kind==='arrow'||s.kind==='dagger'){line(ctx,-18,0,10,0,s.color,s.kind==='dagger'?3:2);poly(ctx,[10,0,3,-4,3,4],s.color,null);if(s.kind==='arrow'){line(ctx,-15,0,-20,-4,'#8b826c');line(ctx,-15,0,-20,4,'#8b826c');}}
 else if(s.kind==='axe'){line(ctx,-11,8,8,-10,'#8b6540',4);poly(ctx,[1,-10,13,-10,17,-1,7,5],s.color);}
 else{ctx.globalCompositeOperation='lighter';ctx.drawImage(s.kind==='fire'?glows.fire:s.hostile?glows.blood:glows.blue,-24,-24,48,48);ellipse(ctx,0,0,s.r,s.r*.75,s.color);ellipse(ctx,-2,-2,s.r*.45,s.r*.35,'#dfc6a5');}ctx.restore();}}
function drawSortedEntitiesV1(){sortCount=0;for(let i=0;i<props.count;i++){const p=props.items[i];if(inView(p.x,p.y)){p.sortType=0;sortList[sortCount++]=p;}}for(let i=0;i<enemies.count;i++){const e=enemies.items[i];if(inView(e.x,e.y,120)){e.sortType=1;sortList[sortCount++]=e;}}for(let i=0;i<allies.count;i++){const a=allies.items[i];if(inView(a.x,a.y)){a.sortType=2;sortList[sortCount++]=a;}}const p=run.player;p.sortType=3;sortList[sortCount++]=p;sortList.length=sortCount;sortList.sort((a,b)=>a.y-b.y);for(let i=0;i<sortCount;i++){const e=sortList[i];if(e.sortType===0){const x=screenX(e.x),y=screenY(e.y);ellipse(ctx,x,y,26,8,'#00000066');ctx.drawImage(getImage(e.type),x-40,y-100,80,110);}else if(e.sortType===1){const size=e.boss>=0?e.boss===2?116:100:e.id===99?88:e.elite?79:58;const alpha=e.behavior==='phase'&&Math.sin(e.age*2.1)<-.25?.32:1;drawActor(e.sprite,e.x,e.y,size,run.player.x<e.x?-1:1,Math.sin(e.age*7)*2,e.flash,alpha);if(e.elite){const x=screenX(e.x),y=screenY(e.y)-size+8;text(L(ENEMIES[e.id].name),x,y,13,'#d5b66b');text(L(MODIFIERS[e.mod1])+' · '+L(MODIFIERS[e.mod2]),x,y+15,10,'#b79b7b');rect(ctx,x-25,y+26,50,3,'#341617');rect(ctx,x-25,y+26,50*clamp(e.hp/e.maxHp,0,1),3,'#b38a42');}else if(e.hp<e.maxHp&&e.boss<0&&e.id!==99){const x=screenX(e.x),y=screenY(e.y)-62;rect(ctx,x-16,y,32,3,'#23181a');rect(ctx,x-16,y,32*clamp(e.hp/e.maxHp,0,1),3,'#854031');}}
 else if(e.sortType===2)drawActor('skeleton',e.x,e.y,54,1,Math.sin(e.walk*7)*2,0,.75);else{const flicker=p.invuln>0&&Math.floor(clock*18)%2===0;drawActor('hero'+selectedHero,p.x,p.y,68,p.facing,Math.sin(p.walk)*2.5,0,flicker?.4:1);}}}
function drawOrbits(){const w=run.weapons.find(w=>w.id===3);if(!w)return;const s=weaponStats(w),n=Math.min(12,s.amount);for(let i=0;i<n;i++){const a=run.time*(w.evolved?2.9:2)+i*TAU/n,x=screenX(run.player.x+Math.cos(a)*s.radius),y=screenY(run.player.y+Math.sin(a)*s.radius);ctx.drawImage(glows.warm,x-20,y-20,40,40);ctx.drawImage(icons.w3,x-13,y-13,26,26);}}
function drawLightingV1(){dc.globalCompositeOperation='source-over';dc.fillStyle='rgba(8,5,5,.82)';dc.fillRect(0,0,270,480);dc.globalCompositeOperation='destination-out';const p=run.player,x=screenX(p.x)/2,y=(screenY(p.y)-20)/2,r=(302+Math.sin(clock*9)*5)/2;dc.drawImage(glows.light,x-r,y-r,r*2,r*2);let lights=1,cap=quality==='low'?6:quality==='high'?20:12;for(let i=0;i<props.count&&lights<cap;i++){const a=props.items[i];if(a.type!=='torch'||!inView(a.x,a.y,160))continue;const sx=screenX(a.x)/2,sy=(screenY(a.y)-60)/2;dc.drawImage(glows.light,sx-58,sy-58,116,116);lights++;}for(let i=0;i<shots.count&&lights<cap;i++){const a=shots.items[i];if(a.kind!=='fire'||!inView(a.x,a.y,90))continue;const sx=screenX(a.x)/2,sy=screenY(a.y)/2;dc.drawImage(glows.light,sx-40,sy-40,80,80);lights++;}dc.globalCompositeOperation='source-over';ctx.drawImage(dark,0,0,540,960);ctx.drawImage(glows.warm,screenX(p.x)-210,screenY(p.y)-230,420,420);}
function drawWorld(){ctx.save();const shake=trauma*trauma*save.settings.shake*12;if(shake)ctx.translate(rand(-shake,shake),rand(-shake,shake));drawFloor();drawDecals();drawPickups();for(let i=0;i<effects.count;i++){const e=effects.items[i];if(GROUND_FX.has(e.kind))drawEffect(e);}drawSortedEntities();drawAuras();drawShots();for(let i=0;i<effects.count;i++){const e=effects.items[i];if(!GROUND_FX.has(e.kind))drawEffect(e);}for(let i=0;i<particles.count;i++){const p=particles.items[i];if(!inView(p.x,p.y,10))continue;ctx.globalAlpha=Math.min(1,p.life/p.max);rect(ctx,screenX(p.x),screenY(p.y),p.size,p.size,p.color);}ctx.globalAlpha=1;drawLighting();if(quality!=='low'){for(let j=0;j<3;j++)ctx.drawImage(glows.fog,Math.sin(clock*.07+j*3)*220-80,((clock*9+j*310)%1300)-300,700,420);}ctx.drawImage(vignette,0,0,CONFIG.W,CONFIG.H);if(quality==='high'){ctx.globalAlpha=.23;const ox=(frameNo*7)%128,oy=(frameNo*3)%128;for(let y=-128;y<960;y+=128)for(let x=-128;x<540;x+=128)ctx.drawImage(grain,x+ox,y+oy);ctx.globalAlpha=1;}for(let i=0;i<numbers.count;i++){const p=numbers.items[i];if(!inView(p.x,p.y,15))continue;ctx.globalAlpha=Math.min(1,p.life*3);text(p.value,screenX(p.x),screenY(p.y),p.big?23:17,p.color,'center',p.big);}ctx.globalAlpha=1;ctx.restore();}
