function orb(x,y,r,ratio,color,label,value){ctx.save();ellipse(ctx,x,y,r+5,r+5,'#0b090a');ctx.strokeStyle='#98733f';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,y,r+3,0,TAU);ctx.stroke();ctx.beginPath();ctx.arc(x,y,r,0,TAU);ctx.clip();ellipse(ctx,x,y,r,r,'#171116');const top=y+r-2*r*clamp(ratio,0,1);ctx.beginPath();ctx.moveTo(x-r,y+r);ctx.lineTo(x-r,top);for(let j=0;j<=14;j++){const a=x-r+j*(2*r/14);ctx.lineTo(a,top+Math.sin(j*.65+clock*3)*2.6);}ctx.lineTo(x+r,y+r);ctx.closePath();ctx.fillStyle=color;ctx.fill();ctx.globalAlpha=.08;ctx.drawImage(glows.light,x-r*.8,y-r*.85,r*1.5,r*1.5);ctx.globalAlpha=.12;ellipse(ctx,x-r*.3,y-r*.45,r*.45,r*.18,'#fff');ctx.globalAlpha=1;ctx.restore();text(value,x,y+3,17,'#eee2c9','center',true);text(label,x,y+r+18,11,'#a49885');}
function actionButton(x,y,r,cd,max,symbol,label){ellipse(ctx,x,y,r+3,r+3,'#0c090b');ellipse(ctx,x,y,r,r,cd>0?'#272021':'#4a271b');ctx.strokeStyle=cd>0?'#6c5238':'#d2a557';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,r,0,TAU);ctx.stroke();if(cd>0){ctx.fillStyle='#0302049e';ctx.beginPath();ctx.moveTo(x,y);ctx.arc(x,y,r,-Math.PI/2,-Math.PI/2+TAU*clamp(cd/max,0,1));ctx.closePath();ctx.fill();}if(cd>0)text(Math.ceil(cd),x,y,22,'#a79883');else if(symbol==='»'){line(ctx,x-10,y-7,x-3,y,'#f2d57a',2);line(ctx,x-3,y,x-10,y+7,'#f2d57a',2);line(ctx,x+2,y-7,x+9,y,'#f2d57a',2);line(ctx,x+9,y,x+2,y+7,'#f2d57a',2);}else{ctx.save();ctx.translate(x,y);ctx.beginPath();for(let j=0;j<8;j++){const a=j*Math.PI/4-Math.PI/2,r=j%2?5:19;if(j===0)ctx.moveTo(Math.cos(a)*r,Math.sin(a)*r);else ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r);}ctx.closePath();ctx.fillStyle=PAL.GOLD_BRIGHT;ctx.fill();ctx.restore();}text(label,x,y+r+16,11,'#ac997d');}
function drawHUDV1(){const p=run.player;frame(20,22,500,18,'#9a773f');rect(ctx,25,27,490*clamp(run.xp/run.nextXP,0,1),8,'#3c6891');text(`${T('level')} ${run.level}`,270,57,17,'#d7bf85');text(fmt(run.time),270,88,28,'#e1d7c1','center',true);ellipse(ctx,31,67,6,7,'#a99e8d');rect(ctx,27,65,3,3,'#171314');rect(ctx,32,65,3,3,'#171314');text(run.kills,45,68,18,'#a99e8d','left');text('◆ '+Math.floor(run.gold),26,94,17,PAL.GOLD,'left');frame(463,54,54,50,'#87683f');rect(ctx,481,66,5,23,'#c4ae80');rect(ctx,493,66,5,23,'#c4ae80');if(run.bosses>0){let j=0;for(let i=0;i<enemies.count;i++){const e=enemies.items[i];if(e.boss<0||e.hp<=0)continue;const y=134+j*48;frame(45,y,450,15,'#c5a050');rect(ctx,50,y+5,440*clamp(e.hp/e.maxHp,0,1),5,'#9b2827');text(L(BOSSES[e.boss].name),270,y-13,16,'#cfb16f');j++;if(j>=3)break;}}else if(run.time<7)text(T('long'),270,142,13,'#ac9b81');
 orb(67,878,43,p.hp/p.maxHp,'#8f1522',T('hp'),Math.ceil(p.hp));orb(473,878,43,run.xp/run.nextXP,'#244e83',T('xp'),Math.floor(run.xp));actionButton(434,770,42,run.skillCD,HEROES[selectedHero].cd,'✦',T('skill'));actionButton(333,835,30,run.dashCD,4,'»',T('dash'));for(let i=0;i<run.weapons.length;i++){const w=run.weapons[i],x=158+i*38;ctx.drawImage(icons['w'+w.id],x,906,32,32);text(w.evolved?'✦':w.level,x+27,935,10,w.evolved?'#8db272':'#cfb478');}for(let i=0,j=0;i<16;i++)if(run.passives[i]){ctx.drawImage(icons['p'+i],160+j*33,869,27,27);text(run.passives[i],183+j*33,892,9,'#c4b286');j++;}
 if(p.hp/p.maxHp<.3){ctx.globalAlpha=.12+.08*Math.sin(clock*6);rect(ctx,0,0,540,12,'#b61520');rect(ctx,0,948,540,12,'#b61520');ctx.drawImage(glows.blood,-180,-220,400,1400);ctx.drawImage(glows.blood,320,-220,400,1400);ctx.globalAlpha=1;}if(Input.pointer!==null){ctx.globalAlpha=save.settings.opacity;const r=save.settings.joystick;ellipse(ctx,Input.ox,Input.oy,r,r,'#100e10');ctx.strokeStyle='#b79a5c';ctx.lineWidth=2;ctx.beginPath();ctx.arc(Input.ox,Input.oy,r,0,TAU);ctx.stroke();ellipse(ctx,Input.ox+Input.x*r*.65,Input.oy+Input.y*r*.65,r*.4,r*.4,'#6a5741');ctx.strokeStyle='#c8a565';ctx.beginPath();ctx.arc(Input.ox+Input.x*r*.65,Input.oy+Input.y*r*.65,r*.4,0,TAU);ctx.stroke();ctx.globalAlpha=1;}else if(run.time<10)text('◉',125,750,60,'#7d6b4655');if(debug){frame(10,195,232,118);text(`${fps.toFixed(0)} FPS · ${quality}`,22,218,16,PAL.GOLD,'left');text(`${T('enemyCount')}: ${enemies.count}/${caps()}`,22,244,15,PAL.BONE,'left');text(`Shots ${shots.count} · Souls ${drops.count}`,22,269,14,PAL.BONE,'left');text(`FX ${effects.count} · Particles ${particles.count}`,22,292,14,PAL.BONE,'left');}}
function drawMenuBackgroundV1(){drawFloor();ctx.fillStyle='#05040550';ctx.fillRect(0,0,540,960);for(let i=0;i<6;i++){const x=i%2?475:65,y=230+Math.floor(i/2)*245;ctx.drawImage(sprites.pillar,x-48,y-115,96,132);ctx.drawImage(sprites.torch,x-40,y-30,80,110);ctx.drawImage(glows.fire,x-100,y-120,200,200);}ctx.save();ctx.translate(270,420);ctx.scale(1,.65);ctx.strokeStyle='#644b30';ctx.lineWidth=3;for(let r=100;r<=180;r+=25){ctx.beginPath();ctx.arc(0,0,r,0,TAU);ctx.stroke();}for(let i=0;i<12;i++){const a=i*TAU/12;line(ctx,Math.cos(a)*115,Math.sin(a)*115,Math.cos(a)*170,Math.sin(a)*170,'#785a34',2);}ctx.restore();ctx.drawImage(glows.blood,20,150,500,660);for(let i=0;i<28;i++){const x=(hash(i,2)%540)+Math.sin(clock*.4+i)*20,y=960-((clock*(12+i%5*4)+hash(i,5)%960)%1040);rect(ctx,x,y,1+i%2,2,'#b2713d88');}ctx.drawImage(vignette,0,0);}
function render(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.imageSmoothingEnabled=true;rect(ctx,0,0,540,960,PAL.BLACK_VOID);if(run&&['RUN','LEVELUP','PAUSE','CHEST','BOSS_INTRO','RESULT'].includes(state)){drawWorld();drawHUD();}else drawMenuBackground();}


/* ==================== UI SCREENS / STATE ==================== */
function hideUI(){rememberScreenScroll();ui.classList.remove('show');ui.style.background='';ui.innerHTML='';screenName='';}
function showUI(html,name=''){screenName=name;ui.classList.add('show');ui.innerHTML='<section class="panel">'+html+'</section>';ui.style.background=['MENU','TITLE','HERO_SELECT','STAGE_SELECT'].includes(state)?'rgba(5,4,5,.26)':'rgba(5,4,5,.72)';}
function button(label,action,cls='',disabled=false){return `<button data-action="${action}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`;}
function backButton(action='menu'){return button(T('back'),action,'back');}
function titleScreen(){state='MENU';showUI(`<div class="eyebrow">${T('original')}</div><div class="crest">✥</div><h1>HELLBOUND<br><span style="font-size:38px;letter-spacing:8px">SURVIVORS</span></h1><div class="rule"></div><p class="subtitle">${L(['The bells toll for the living.','Камбаните бият за живите.'])}</p><div style="height:40px"></div>${button(T('begin'),'begin','primary back')}<div class="credits">${T('offline')}</div>`,'title');ui.querySelector('.panel').style.cssText='background:transparent;box-shadow:none;border:0;outline:0';}
function menuV1(){state='MENU';Input.reset();showUI(`<div class="eyebrow">${T('original')}</div><h1 style="font-size:44px">HELLBOUND<br><span style="font-size:31px;letter-spacing:7px">SURVIVORS</span></h1><div class="rule"></div><p class="subtitle">${L(['One soul. Twelve minutes. No mercy.','Една душа. Дванадесет минути. Без милост.'])}</p><div class="stack">${button(T('play'),'play','primary')}${button(T('crypt')+' · ◆ '+save.gold,'crypt')}<div class="row">${button(T('heroes'),'heroes')}${button(T('achievements'),'achievements')}</div>${button(T('settings'),'settings')}</div><p class="credits">${T('offline')}<br>v1.0 · HELLBOUND</p>`,'menu');}
function heroScreenV1(){state='HERO_SELECT';const h=HEROES[selectedHero],unlocked=save.unlockedHeroes.includes(selectedHero);showUI(`<div class="eyebrow">${selectedHero+1} / ${HEROES.length}</div><h2>${T('chooseHero')}</h2><div class="hero-view"><img alt="${L(h.name)}" src="${imageURL('hero'+selectedHero)}"></div><div class="row">${button('‹','heroPrev')}<h3>${L(h.name)}</h3>${button('›','heroNext')}</div><p class="subtitle">${L(h.trait)}</p><div class="tag">${L(h.skill)}</div><p class="small">${T('weapon')}: ${L(WEAPONS[h.weapon].name)}</p><div class="rule"></div>${unlocked?button(T('continue'),'stage','primary back'):`<p class="danger">${T('locked')} · ${L(h.hint)}</p>`}${backButton()}<p class="credits">${T('help')}</p>`,'hero');}
function stageScreenV1(){state='STAGE_SELECT';let html=`<h2>${T('chooseStage')}</h2>`;for(let i=0;i<3;i++){const unlocked=save.unlockedStages.includes(i);html+=`<button class="card" data-action="stage${i}" ${unlocked?'':'disabled'} style="min-height:105px;${selectedStage===i?'border-color:#d3af62;background:linear-gradient(100deg,#463021,#161315)':''}"><span style="font-size:36px;color:#a68b55">${['✝','♜','♨'][i]}</span><span><h3>${T('stage'+i)}</h3><p>${unlocked?`${T('best')}: ${fmt(save.best[i])} · ${T('win')}: ${save.wins[i]}`:T('stageLock')}</p></span></button>`;}html+=`<div class="setting"><label>${T('curse')}</label><select id="curse"><option value="1" ${curseChoice===1?'selected':''}>100%</option><option value="1.25" ${curseChoice===1.25?'selected':''}>125%</option><option value="1.5" ${curseChoice===1.5?'selected':''}>150%</option></select></div><p class="small">${T('long')}</p>${button(T('start'),'start','primary back')}${backButton('heroes')}`;showUI(html,'stage');}
function showPause(){if(!run||run.ended)return;state='PAUSE';Input.reset();showUI(`<div class="crest">✥</div><h2>${T('pause')}</h2><p class="subtitle">${fmt(run.time)} · ${T('level')} ${run.level} · ☠ ${run.kills}</p><div class="stack">${button(T('resume'),'resume','primary')}${button(T('settings'),'settingsPause')}${button(T('quit'),'quit')}</div>`,'pause');}
function showLevelup(){state='LEVELUP';run.pending=Math.max(1,run.pending);Input.reset();banishMode=false;choices=rollChoices();Sound.play('level');vibrate(35);renderLevelup();}
function choiceCard(o,index=null){const isW=o.type==='w'||o.type==='evo',d=isW?WEAPONS[o.id]:o.type==='p'?PASSIVES[o.id]:null,w=isW?run.weapons.find(w=>w.id===o.id):null,rank=isW?(w?w.level:0):o.type==='p'?run.passives[o.id]:0;let name,desc,color,rarity,icon,flavor='';if(d){name=L(o.type==='evo'?d.evo:d.name);color=o.type==='evo'?'#8db272':isW?['#d9cfb8','#7b9ebd','#dbc56c'][d.rarity]:'#ac9bc1';rarity=o.type==='evo'?T('evolved'):isW?T(['common','magic','rare'][d.rarity]):T('passive');icon=(isW?'w':'p')+o.id;if(isW){const next=d.levels[Math.min(7,rank)],current=d.levels[Math.max(0,rank-1)];desc=L(d.desc)+`<br><span style="color:#c8ae78">${L(['Damage','Щети'])} ${rank?displayNumber(current.damage)+' → ':''}${displayNumber(next.damage)} · ${displayNumber(next.cooldown,2)}s</span>`;flavor=L(d.flavor);}else desc=L(d.desc);name+=o.type==='evo'?'':` <small style="font:12px system-ui;color:#a49786">${rank?rank+' → '+Math.min(isW?8:5,rank+1):T('new')}</small>`;}else{name=T(o.type==='gold'?'goldGift':'heal');desc=o.type==='gold'?'+40 ◆':'+35% '+T('hp');color=PAL.GOLD;rarity=T('common');icon=o.type==='gold'?'p14':'p8';}
 return `<${index===null?'div':'button'} class="card" ${index===null?'':`data-action="choice${index}"`} style="border-left:3px solid ${color};${choices.length===4?'min-height:108px;margin:7px 0;padding:12px':''}"><img alt="" src="${imageURL(icon)}"><span><h3 style="color:${color}">${name}</h3><p>${desc}</p>${flavor?`<p class="flavor">${flavor}</p>`:''}<p class="rarity" style="color:${color}">${rarity}</p></span></${index===null?'div':'button'}>`;}
function renderLevelup(){showUI(`<div class="eyebrow">${T('level')} ${run.level}</div><h2>${T('levelup')}</h2><p class="small">${T(banishMode?'banishHint':'choose')}</p>${choices.map((c,i)=>choiceCard(c,i)).join('')}<div class="row">${button(T('reroll')+' · '+run.rerolls,'reroll','',run.rerolls<=0)}${button((banishMode?T('cancel'):T('banish'))+' · '+run.banishes,'banish','',run.banishes<=0)}</div><p class="credits">${T('evolutionHint')}</p>`,'levelup');}
function showChest(){showUI(`<div class="crest" style="color:#e1bd68">✧</div><h2>${T('chest')}</h2><p class="small">${T('chestLoot')}</p>${run.chestRewards.map(o=>choiceCard(o)).join('')}${button(T('open'),'closeChest','primary back')}`,'chest');}
function showBossIntroV1(e){if(run.ended)return;state='BOSS_INTRO';Input.reset();showUI(`<div class="eyebrow danger">${T('boss')}</div><div class="hero-view"><img alt="" src="${imageURL(e.sprite)}" style="height:180px"></div><h2 style="color:#c15b45">${L(BOSSES[e.boss].name)}</h2><p class="subtitle">${L([['Watch the ground. Evade the charge.','Следи земята. Избягвай атаката.'],['Her thirst grows with every wound.','Жаждата ѝ расте с всяка рана.'],['The last seal is broken. End the darkness.','Последният печат е счупен. Победи мрака.']][e.boss])}</p>${button(T('continue'),'resume','primary back')}`,'boss');}
function showResultV1(){const r=run;showUI(`<div class="eyebrow">${T('stage'+r.stage)}</div><h2 class="result-title ${r.victory?'victory':''}">${T(r.victory?'win':'dead')}</h2><div class="stat-grid"><div><b>${fmt(r.time)}</b>${T('time')}</div><div><b>${r.kills}</b>${T('kills')}</div><div><b>${Math.floor(r.gold)}</b>${T('gold')}</div><div><b>${r.level}</b>${T('level')}</div></div><div class="equipment">${r.weapons.map(w=>`<img alt="${L(WEAPONS[w.id].name)}" src="${imageURL('w'+w.id)}" style="border:1px solid ${w.evolved?'#8da763':'#5b4530'}">`).join('')}</div>${r.fresh?`<p style="color:#d8bb75">${T('unlock')}</p>`:''}<p class="small">${T('soulstones')}: +${r.soulstones} · ${T('gold')}: ${save.gold}</p><div class="stack" style="margin-top:18px">${button(T('retry'),'start','primary')}${button(T('crypt'),'crypt')}${button(T('menu'),'menu')}</div>`,'result');}
function cryptScreen(){state='CRYPT';let html=`<h2>${T('crypt')}</h2><p class="subtitle">◆ ${save.gold} · ✧ ${save.soulstones}</p>`;for(const m of META){const n=metaLv(m.id),cost=metaCost(m);html+=`<div class="shop-row"><div><h3>${T(m.id)}</h3><p class="small">${n} / ${m.max} · ${['health','might','speed','growth','greed','luck','cooldown','curseStat'].includes(m.id)?Math.round(m.value*100)+'%':'+'+m.value} / ${T('level')}</p></div>${button(n>=m.max?T('max'):'◆ '+cost,'buy_'+m.id,'',n>=m.max||save.gold<cost)}</div>`;}html+=backButton();showUI(html,'crypt');}
function achievementScreen(){state='ACHIEVEMENTS';let html=`<h2>${T('achievements')}</h2><p class="small">☠ ${save.kills} · ${T('totalKills')}</p>`;for(let i=0;i<ACHIEVEMENTS.length;i++){const a=ACHIEVEMENTS[i],v=a.metric.startsWith('win')?save.campaign.wins[[3,7,15][Number(a.metric.slice(-1))]]:save[a.metric],done=v>=a.goal;html+=`<div style="text-align:left;margin:22px 0"><h3 style="color:${done?'#d8ba70':'#998f82'}">${done?'✦':'◇'} ${L(a.name)}</h3><div class="progress"><i style="width:${clamp(v/a.goal*100,0,100)}%"></i></div><p class="small">${Math.min(v,a.goal)} / ${a.goal}</p></div>`;}html+=backButton();showUI(html,'achievements');}
let settingsReturn='menu';
function settingsScreen(back='menu'){settingsReturn=back;if(back!=='pause')state='SETTINGS';const s=save.settings;let html=`<h2>${T('settings')}</h2><div class="setting"><label>${T('language')}</label><select data-setting="lang"><option value="bg" ${s.lang==='bg'?'selected':''}>Български</option><option value="en" ${s.lang==='en'?'selected':''}>English</option></select></div>`;for(const [key,label] of [['music','music'],['sfx','sfx'],['shake','shake'],['opacity','opacity']])html+=`<div class="setting"><label>${T(label)}</label><input aria-label="${T(label)}" data-setting="${key}" type="range" min="0" max="1" step=".05" value="${s[key]}"></div>`;html+=`<div class="setting"><label>${T('joystick')}</label><input aria-label="${T('joystick')}" data-setting="joystick" type="range" min="45" max="90" step="5" value="${s.joystick}"></div>`;for(const [key,label] of [['mute','mute'],['vibration','vibration'],['numbers','damageNumbers']])html+=`<div class="setting"><label for="set_${key}">${T(label)}</label><input id="set_${key}" data-setting="${key}" type="checkbox" ${s[key]?'checked':''}></div>`;html+=`<div class="setting"><label>${T('quality')}</label><select data-setting="quality">${['auto','low','medium','high'].map((q,i)=>`<option value="${q}" ${s.quality===q?'selected':''}>${L([['Auto','Автоматично'],['Low','Ниска'],['Medium','Средна'],['High','Висока']][i])}</option>`).join('')}</select></div><div class="row">${button(T('export'),'export')}${button(T('import'),'import')}</div><textarea id="saveText" spellcheck="false" aria-label="${T('export')}" placeholder="${T('export')} / ${T('import')}"></textarea><p class="small">${T('sourceNote')}</p><p class="small audio-credit">${L(['Synthesized effects · Ambient music','Синтезирани звукови ефекти и фонова музика'])}</p>${button(T('fullscreen'),'fullscreen','back')}${backButton(back==='pause'?'pause':'menu')}`;showUI(html,'settings');}
function resumeRun(){if(!run||run.ended)return;state='RUN';hideUI();Input.reset();Sound.unlock();requestWake();if(run.pending>0)showLevelup();}
/** UI actions contain only fixed identifiers, never user-provided code. */
function uiActionV1(action){Sound.unlock();Sound.play('ui');if(action.startsWith('choice'))return chooseUpgrade(Number(action.slice(6)));if(action.startsWith('buy_')){const m=META.find(x=>x.id===action.slice(4));if(m&&metaLv(m.id)<m.max&&save.gold>=metaCost(m)){save.gold-=metaCost(m);save.meta[m.id]=metaLv(m.id)+1;persist();cryptScreen();Sound.play('coin');}return;}if(/^stage[0-2]$/.test(action)){const n=Number(action.slice(-1));if(save.unlockedStages.includes(n)){selectedStage=n;stageScreen();}return;}
 switch(action){case 'begin':unlockDevice();menu();break;case 'menu':menu();break;case 'play':case 'heroes':heroScreen();break;case 'heroPrev':selectedHero=(selectedHero+5)%6;heroScreen();break;case 'heroNext':selectedHero=(selectedHero+1)%6;heroScreen();break;case 'stage':if(save.unlockedHeroes.includes(selectedHero))stageScreen();break;case 'start':if(save.unlockedHeroes.includes(selectedHero)&&save.unlockedStages.includes(selectedStage)){unlockDevice();startRun();}break;case 'crypt':cryptScreen();break;case 'achievements':achievementScreen();break;case 'settings':settingsScreen();break;case 'settingsPause':settingsScreen('pause');break;case 'pause':showPause();break;case 'resume':resumeRun();break;case 'quit':showUI(`<h2>${T('quit')}</h2><p class="subtitle">${T('quitConfirm')}</p><div class="stack">${button(T('confirm'),'confirmQuit','primary')}${button(T('cancel'),'pause')}</div>`,'quit');break;case 'confirmQuit':finishRun(false);break;case 'reroll':if(run.rerolls>0){run.rerolls--;choices=rollChoices();banishMode=false;renderLevelup();}break;case 'banish':if(run.banishes>0){banishMode=!banishMode;renderLevelup();}break;case 'closeChest':resumeRun();break;case 'export':{const a=document.getElementById('saveText');a.value=JSON.stringify(save);a.focus({preventScroll:true});a.select();toast(T('copied'));break;}case 'import':{try{const a=document.getElementById('saveText'),s=normalizeSave(JSON.parse(a.value));save=s;persist();updateUnlocks();settingsScreen(settingsReturn);Sound.volumes();toast(T('imported'));}catch(_){toast(T('invalid'));}break;}case 'fullscreen':unlockDevice();break;}}
/* ==================== INPUT / LIFECYCLE ==================== */
const Input={x:0,y:0,ox:0,oy:0,pointer:null,keys:{},lastRight:-10,reset(){this.x=0;this.y=0;this.pointer=null;this.keys={};}};
function point(event){const r=stage.getBoundingClientRect();return {x:(event.clientX-r.left)/viewScale,y:(event.clientY-r.top)/viewScale};}
function pointerDownV1(e){if(e.target!==canvas)return;e.preventDefault();if(state!=='RUN')return;Sound.unlock();const q=point(e);try{canvas.setPointerCapture(e.pointerId);}catch(_){}if(q.y<110&&q.x>455){showPause();return;}if(q.y>62&&q.y<110&&q.x>205&&q.x<330){if(clock>tapDeadline)timerTaps=0;tapDeadline=clock+1.2;if(++timerTaps>=5){debug=!debug;timerTaps=0;}return;}if((q.x-434)**2+(q.y-770)**2<55**2){activeSkill();return;}if((q.x-333)**2+(q.y-835)**2<45**2){dash();return;}if(q.x<270&&Input.pointer===null){Input.pointer=e.pointerId;Input.ox=q.x;Input.oy=q.y;Input.x=0;Input.y=0;}else if(q.x>=270){if(clock-Input.lastRight<.3){dash();Input.lastRight=-10;}else Input.lastRight=clock;}}
function pointerMove(e){if(state!=='RUN'||e.pointerId!==Input.pointer)return;e.preventDefault();const p=point(e),r=save.settings.joystick,dx=p.x-Input.ox,dy=p.y-Input.oy,n=Math.hypot(dx,dy),m=Math.min(1,n/r);if(m<.1){Input.x=0;Input.y=0;}else{Input.x=dx/(n||1)*m;Input.y=dy/(n||1)*m;}}
function pointerUp(e){if(e.pointerId===Input.pointer){Input.pointer=null;Input.x=0;Input.y=0;}}
function resize(){const w=window.visualViewport?.width||window.innerWidth,h=window.visualViewport?.height||window.innerHeight;let st=0,sb=0,sl=0,sr=0;try{const css=getComputedStyle(document.documentElement);st=parseFloat(css.getPropertyValue('--sat'))||0;sb=parseFloat(css.getPropertyValue('--sab'))||0;sl=parseFloat(css.getPropertyValue('--sal'))||0;sr=parseFloat(css.getPropertyValue('--sar'))||0;}catch(_){}const aw=w-sl-sr,ah=h-st-sb;viewScale=Math.min(aw/540,ah/960);stage.style.transform=`scale(${viewScale})`;stage.style.left=sl+(aw-540*viewScale)/2+'px';stage.style.top=st+(ah-960*viewScale)/2+'px';dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(540*dpr);canvas.height=Math.round(960*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.imageSmoothingEnabled=false;}
async function requestWake(){try{if(!wake&&navigator.wakeLock&&state==='RUN'){wake=await navigator.wakeLock.request('screen');wake.addEventListener('release',()=>{wake=null;});}}catch(_){}}
function unlockDevice(){Sound.unlock();try{const f=document.documentElement.requestFullscreen?.();if(f&&f.catch)f.catch(()=>{});}catch(_){}try{const p=screen.orientation?.lock?.('portrait');if(p&&p.catch)p.catch(()=>{});}catch(_){}requestWake();}
function installManifest(){try{const s=surface(192,192),c=s.getContext('2d');rect(c,0,0,192,192,'#0a0707');c.drawImage(sprites.hero0,20,-3,152,190);const manifest={name:'Hellbound Survivors',short_name:'Hellbound',display:'fullscreen',orientation:'portrait',start_url:location.href,theme_color:'#0a0707',background_color:'#0a0707',icons:[{src:s.toDataURL(),sizes:'192x192',type:'image/png'}]},link=document.createElement('link');link.rel='manifest';link.href=URL.createObjectURL(new Blob([JSON.stringify(manifest)],{type:'application/manifest+json'}));document.head.appendChild(link);}catch(_){}}
