ui.addEventListener('input',e=>{const el=e.target,k=el.dataset.setting;if(!k)return;save.settings[k]=el.type==='checkbox'?el.checked:el.type==='range'?Number(el.value):el.value;Sound.volumes();if(k==='quality')quality=el.value==='auto'?'medium':el.value;persist();if(k==='lang'){document.documentElement.lang=save.settings.lang;settingsScreen(settingsReturn);}});
