window.addEventListener('keydown',e=>{const tag=document.activeElement?.tagName;if(tag==='TEXTAREA'||tag==='INPUT'||tag==='SELECT')return;const k=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Escape','p','w','a','s','d'].includes(k))e.preventDefault();if(k==='Escape'||k==='p'){if(state==='RUN')showPause();else if(state==='PAUSE'&&screenName==='pause')resumeRun();return;}if(state==='RUN'){Input.keys[k]=true;if(!e.repeat&&k===' ')activeSkill();if(!e.repeat&&k==='Shift')dash();if(!e.repeat&&k==='1')activeSkill(0);if(!e.repeat&&k==='2')activeSkill(1);if(!e.repeat&&k==='3')activeSkill(2);}});
window.addEventListener('keyup',e=>{const k=e.key.length===1?e.key.toLowerCase():e.key;Input.keys[k]=false;});
window.addEventListener('blur',()=>{Input.reset();if(state==='RUN')showPause();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(state==='RUN')showPause();Input.reset();persist();Sound.suspend();wake?.release().catch(()=>{});}else{lastTime=performance.now();}});
window.addEventListener('popstate',()=>{if(run&&!run.ended&&['RUN','PAUSE','LEVELUP','CHEST','BOSS_INTRO'].includes(state)){if(state==='RUN')showPause();else if(state==='PAUSE')showPause();try{history.pushState({hellbound:true},'');}catch(_){}}});
