/* ==================== FIXED-TIMESTEP GAME LOOP / BOOT ==================== */
let lastTime=0,accumulator=0;const qualityMeasure={time:0,sum:0,n:0,window:0,slow:0};
function loop(now){if(!lastTime)lastTime=now;const raw=now-lastTime;lastTime=now;const delta=clamp(raw/1000,0,.05);clock+=delta;frameNo++;frameMs=lerp(frameMs,raw||16.7,.04);fps=1000/Math.max(1,frameMs);if(state==='RUN'){accumulator+=delta;let steps=0;while(accumulator>=CONFIG.STEP&&state==='RUN'&&steps<3){updateRun(CONFIG.STEP);accumulator-=CONFIG.STEP;steps++;}if(state!=='RUN')accumulator=0;if(save.settings.quality==='auto'&&raw<120){qualityMeasure.time+=delta;qualityMeasure.sum+=raw;qualityMeasure.n++;if(qualityMeasure.time>3){const avg=qualityMeasure.sum/Math.max(1,qualityMeasure.n);if(avg>22&&quality!=='low'){quality=quality==='high'?'medium':'low';}qualityMeasure.time=0;qualityMeasure.sum=0;qualityMeasure.n=0;}}}else accumulator=0;Sound.tick();render();requestAnimationFrame(loop);}
function bootV1(){resize();buildArt();buildOverlays();installManifest();updateUnlocks();titleScreen();requestAnimationFrame(loop);}



