function campaignDefaults(){return {cleared:Array(16).fill(false),best:Array(16).fill(0),wins:Array(16).fill(0),checkpoint:null};}
function defaultsV34(){const s=defaultsV1();s.version=2;s.campaign=campaignDefaults();s.wins=Array(16).fill(0);s.best=Array(16).fill(0);return s;}
function normalizeSaveV34(x){const s=normalizeSaveV1(x);s.version=2;s.campaign=campaignDefaults();if(x.campaign&&typeof x.campaign==='object'){const c=x.campaign;let continuous=true;for(let i=0;i<16;i++){s.campaign.cleared[i]=continuous&&c.cleared?.[i]===true;if(!s.campaign.cleared[i])continuous=false;s.campaign.best[i]=clamp(Number(c.best?.[i])||0,0,10000);s.campaign.wins[i]=s.campaign.cleared[i]?clamp(Math.floor(Number(c.wins?.[i])||1),1,1e6):0;}const p=c.checkpoint;if(p&&Number.isInteger(p.stage)&&p.stage>0&&p.stage<16&&s.campaign.cleared[p.stage-1]&&Number.isInteger(p.hero)&&p.hero>=0&&p.hero<6&&s.unlockedHeroes.includes(p.hero)){s.campaign.checkpoint={stage:p.stage,hero:p.hero,level:clamp(Math.floor(Number(p.level)||1),1,100),xp:clamp(Number(p.xp)||0,0,1e5),weapons:[],passives:Array(16).fill(0)};const cp=s.campaign.checkpoint,ids=new Set();for(const w of Array.isArray(p.weapons)?p.weapons:[]){if(!Number.isInteger(w.id)||w.id<0||w.id>11||ids.has(w.id)||cp.weapons.length>=6)continue;ids.add(w.id);cp.weapons.push({id:w.id,level:clamp(Math.floor(Number(w.level)||1),1,8),evolved:w.evolved===true&&w.level===8});}let n=0;for(let i=0;i<16;i++){const v=clamp(Math.floor(Number(p.passives?.[i])||0),0,5);if(v&&n<6){cp.passives[i]=v;n++;}}if(!cp.weapons.length)s.campaign.checkpoint=null;}}s.wins=[...s.campaign.wins];s.best=[...s.campaign.best];s.unlockedStages=Array.from({length:Math.min(16,s.campaign.cleared.filter(Boolean).length+1)},(_,i)=>i);return s;}
