Object.assign(STR.bg,{campaign:'КАМПАНИЯ',chapter:'Зона',sublevel:'Подниво',guardian:'Пазител',nextLevel:'Към следващото подниво',carry:'Екипировката и нивото на душата се пренасят.',completed:'ЗАВЪРШЕНО',available:'ДОСТЪПНО',lockedPath:'Победи в предишното подниво, за да отключиш.',mana:'Мана',noMana:'Недостатъчно мана',noCorpse:'Няма паднали тела наблизо',movement:'Придвижване',skills:'Класови умения',checkpoint:'Продължи пътешествието',levelClear:'ПОДНИВОТО Е ПРЕМИНАТО',campaignClear:'ЧЕТИРИТЕ ПЕЧАТА СА СЧУПЕНИ',bossSoon:'Оцелей, после победи пазителя',help:'Движение вляво · три умения вдясно · придвижване отдолу',tutorial:'Плъзгай вляво. Атаките са автоматични. Вдясно са трите класови умения; долният бутон скача, щурмува или телепортира по посоката ти.',long:'Победи пазителя, за да отвориш следващата порта.',mastery:'МАЙСТОРСТВО',wells:'Кладенците възстановяват живот и мана',continueLost:'Няма наличен контролен запис',spellSource:'Класически умения · адаптирани за оцеляване'});
function levelInfo(id=run?.stage??selectedStage){return LEVELS[clamp(id,0,15)];}
function unlockedLevel(id){return id===0||id>0&&id<16&&save.campaign.cleared[id-1];}
function stats(){statsV1();if(selectedHero===5){run.player.speed*=1.1;run.player.crit+=.1;}run.player.maxMana=100;run.player.mana=clamp(run.player.mana??100,0,100);}
function startRun(carry=null){if(!unlockedLevel(selectedStage))return;startRunV1();grid.build();run.skillCDs=[0,0,0];run.guardianSpawned=false;run.eliteMarks=0;run.ambientTick=0;run.act=Math.floor(run.stage/4);run.sub=run.stage%4;run.player.mana=100;run.player.leapTime=0;run.player.leapMax=0;run.player.z=0;run.player.attackPose=0;run.player.drawAngle=0;run.player.buffPower=0;run.player.shieldTime=0;run.player.strafeTime=0;run.player.strafeTick=0;run.player.spinTick=0;run.player.moveType='';run.player.vx=0;run.player.vy=0;if(carry&&carry.hero===selectedHero){run.level=clamp(carry.level,1,100);run.xp=clamp(carry.xp,0,xpToNext(run.level)-1);run.nextXP=xpToNext(run.level);run.weapons=carry.weapons.map(w=>({id:w.id,level:w.level,evolved:w.evolved,cd:.25}));run.passives=new Uint8Array(carry.passives);stats();run.player.hp=run.player.maxHp;}world.cx=1e9;world.stream();toast(`${T('chapter')} ${run.act+1} · ${run.sub+1}/4 — ${L(levelInfo().name)}`);}
function updateUnlocks(){if(!save.campaign)save.campaign=campaignDefaults();save.unlockedStages=LEVELS.filter(l=>unlockedLevel(l.id)).map(l=>l.id);const old=save.unlockedHeroes.length;if((save.maxLevel>=15||save.campaign.cleared[0])&&!save.unlockedHeroes.includes(2))save.unlockedHeroes.push(2);if((save.kills>=1000||save.campaign.cleared[2])&&!save.unlockedHeroes.includes(3))save.unlockedHeroes.push(3);if(save.campaign.cleared[3]&&!save.unlockedHeroes.includes(4))save.unlockedHeroes.push(4);for(let i=0;i<ACHIEVEMENTS.length;i++){const a=ACHIEVEMENTS[i],v=a.metric.startsWith('win')?save.campaign.wins[[3,7,15][Number(a.metric.slice(-1))]]:save[a.metric];if(v>=a.goal&&!save.achievements.includes(i))save.achievements.push(i);}return old!==save.unlockedHeroes.length;}
function finishRun(victory){if(!run||run.ended)return;run.ended=true;run.victory=victory;save.gold+=Math.floor(run.gold);save.soulstones+=run.soulstones;save.kills+=run.kills;save.runs++;save.maxLevel=Math.max(save.maxLevel,run.level);const c=save.campaign;c.best[run.stage]=Math.max(c.best[run.stage],run.time);if(victory){c.cleared[run.stage]=true;c.wins[run.stage]++;if(run.stage===7&&run.revived===0&&!save.unlockedHeroes.includes(5))save.unlockedHeroes.push(5);if(run.stage<15)c.checkpoint={stage:run.stage+1,hero:selectedHero,level:run.level,xp:run.xp,weapons:run.weapons.map(w=>({id:w.id,level:w.level,evolved:w.evolved})),passives:Array.from(run.passives)};else c.checkpoint=null;}save.wins=[...c.wins];save.best=[...c.best];run.fresh=updateUnlocks();persist();state='RESULT';Input.reset();Sound.play(victory?'level':'boss');showResult();}
function spawnEnemy(id=0,elite=false,x=null,y=null,boss=-1){const e=spawnEnemyV1(id,elite,x,y,boss);if(e){e.levelGuardian=false;e.colorAct=run.act;e.attackPose=0;e.drawAngle=0;if(boss<0&&id!==99){e.maxHp*=1.65*(1+run.stage*.12+run.time/60*.13);e.hp=e.maxHp;e.speed*=1.08+Math.min(.22,run.time/600)+run.act*.025;e.damage*=1+run.act*.12;}if(boss>=0){e.levelGuardian=true;e.name=levelInfo().guardian;const difficulty=1+run.stage*.34;const budget=run.stage<4?1100+run.stage*420:2400+run.stage*760;e.maxHp=budget*run.player.curse;e.hp=e.maxHp;e.damage=Math.min(38,18+run.stage*1.3);e.speed*=.8;e.cd=2.8;showBossIntro(e);}Terrain.place(e,e.r);}return e;}
function enemyDeath(e){enemyDeathV1(e);if(e.levelGuardian){if(e.boss!==2)run.gold+=(90+run.stage*12)*run.player.greed;run.finalDefeated=true;run.victoryChest=true;openChest(run.sub===3?5:3);}if(Math.random()<.07){const d=drop(e.x+8,e.y,'mana',15);if(d)d.age=0;}}
function hurt(damage,source=null){if(run.player.shieldTime>0)damage*=.55;hurtV1(damage,source);}
function waveDirector(dt){const info=levelInfo(),minute=run.time/48+run.stage*.65;run.spawn-=dt;if(run.spawn<=0&&!run.guardianSpawned){run.spawn+=(run.stage<4?.64:.51)/Math.sqrt(run.player.curse);const n=Math.min(8,1+Math.floor(run.time/42)+Math.floor(run.stage/4));for(let j=0;j<n;j++){let sum=0;for(const d of ENEMIES)if(d.minMinute<=minute)sum+=d.weight;let r=rand(0,sum),id=0;for(const d of ENEMIES)if(d.minMinute<=minute){r-=d.weight;if(r<=0){id=d.id;break;}}spawnEnemy(id);}}const mark=Math.floor(run.time/60);if(mark>run.eliteMarks&&run.time<info.duration-12){run.eliteMarks=mark;spawnEnemy(Math.min(13,3+run.act*3),true);if(mark===2&&run.act>0)swarm(run.act===2?8:1,14);}
 if(run.time>=info.duration&&!run.guardianSpawned){run.guardianSpawned=true;spawnEnemy(0,false,null,null,info.boss);}if(run.time>=info.duration+180&&!run.reaper){run.reaper=true;spawnEnemy(99);toast(T('reaper'));}if(run.guardianSpawned){run.spawn-=dt;if(run.spawn<0){run.spawn=2.4;spawnEnemy(Math.min(13,run.act*3));}}}
/* Restore old saves without fabricating completion of the new campaign. */
save=normalizeSave(save);


