function drawFloor(){const cam=run?run.cam:{x:Math.sin(clock*.03)*70,y:clock*5},id=run?run.stage:Math.floor(clock/12)%4*4,ox=cam.x-270,oy=cam.y-470,tx=Math.floor(ox/256),ty=Math.floor(oy/256);for(let y=ty;y<=ty+4;y++)for(let x=tx;x<=tx+3;x++)ctx.drawImage(worldFloors[id][hash(x,y,run?.seed||76)%3],Math.floor(x*256-ox),Math.floor(y*256-oy));if(run&&run.sub===3){const x=screenX(0),y=screenY(0);ctx.save();ctx.translate(x,y);ctx.scale(1,.52);ctx.lineWidth=3;ctx.strokeStyle=['#a89e7a55','#91a0ba55','#8b9c6d55','#d27e4e66'][run.act];for(let r=145;r<260;r+=35){ctx.beginPath();ctx.arc(0,0,r,0,TAU);ctx.stroke();}for(let j=0;j<12;j++){const a=j*TAU/12;line(ctx,Math.cos(a)*175,Math.sin(a)*175,Math.cos(a)*245,Math.sin(a)*245,ctx.strokeStyle,3);}ctx.restore();}}
function drawActor(id,x,y,size=70,flip=1,bob=0,flash=0,alpha=1,entity=null){const sx=screenX(x),sy=screenY(y),isHero=id.startsWith('hero'),p=run?.player;let a=entity?.drawAngle||0,pose='idle',phase=0,z=0;if(isHero&&p){const moving=Math.hypot(p.vx,p.vy)>8;a=moving?p.drawAngle:p.attackPose>0?p.attackAngle:p.drawAngle;
 if(p.leapTime>0){pose='jump';z=p.z;}
 else if(moving){pose='walk';phase=Math.floor(p.walk)%8;}
 else if(p.attackPose>0){pose='attack';phase=clamp(Math.floor((1-p.attackPose/(p.attackMax||.3))*4),0,3);}}
 else if(entity){a=entity.drawAngle??Math.atan2(p.y-y,p.x-x);const moving=(entity.moveSpeed??120)>4;pose=moving?'walk':entity.action>0?'attack':'idle';phase=pose==='walk'?Math.floor(entity.walk??entity.age*9)%8:pose==='attack'?1:0;}
 let dir=((Math.round(a/TAU*8)%8)+8)%8;const image=actorFrame(id,dir,phase,pose),w=size*1.25,h=w*128/96;ctx.globalAlpha=alpha*(z?Math.max(.2,1-z/140):1);ellipse(ctx,sx,sy+2,size*.28*(1-z/200),size*.11*(1-z/200),'#05060799');ctx.globalAlpha=alpha;ctx.drawImage(image,sx-w/2,sy-h+14-z,w,h);if(flash>0){ctx.globalAlpha=alpha*.18;ctx.fillStyle='#eee9d3';ctx.beginPath();ctx.ellipse(sx,sy-size*.55-z,size*.2,size*.45,0,0,TAU);ctx.fill();}ctx.globalAlpha=1;}
function drawScenery(p){const x=screenX(p.x),y=screenY(p.y),h=['arch','deadTree','obelisk','root'].includes(p.type)?180:145,w=h*160/210;ellipse(ctx,x,y+1,w*.3,8,'#080b0a66');ctx.drawImage(getImage(p.type),x-w/2,y-h+8,w,h);if(p.type==='brazier'){ctx.globalCompositeOperation='lighter';ctx.drawImage(glows.fire,x-48,y-112,96,96);ctx.globalCompositeOperation='source-over';}if(p.type==='well'&&!p.used){ctx.globalAlpha=.3+.12*Math.sin(clock*2);ctx.drawImage(glows.blue,x-35,y-40,70,50);ctx.globalAlpha=1;}}
function drawSortedEntities(){sortCount=0;for(let i=0;i<props.count;i++){const p=props.items[i];if(inView(p.x,p.y,180)){p.sortType=0;sortList[sortCount++]=p;}}for(let i=0;i<enemies.count;i++){const e=enemies.items[i];if(inView(e.x,e.y,150)){e.sortType=1;sortList[sortCount++]=e;}}for(let i=0;i<allies.count;i++){const a=allies.items[i];if(inView(a.x,a.y)){a.sortType=2;sortList[sortCount++]=a;}}const p=run.player;p.sortType=3;sortList[sortCount++]=p;sortList.length=sortCount;sortList.sort((a,b)=>a.y-b.y);for(let i=0;i<sortCount;i++){const e=sortList[i];if(e.sortType===0){drawScenery(e);continue;}if(e.sortType===3){const flicker=p.invuln>0&&p.leapTime<=0&&Math.floor(clock*18)%2===0;drawActor('hero'+selectedHero,p.x,p.y,76,p.facing,0,0,flicker?.5:1,p);continue;}if(e.sortType===2){drawActor(e.shadow?'shade':'skeleton',e.x,e.y,61,1,0,0,.8,{age:0,walk:e.walk,moveSpeed:e.moveSpeed,drawAngle:e.drawAngle,action:0});continue;}const size=e.boss>=0?e.boss===2?112:99:e.id===99?88:e.elite?84:e.id===1?60:68,alpha=e.behavior==='phase'&&Math.sin(e.age*2.1)<-.25?.3:1;drawActor(e.sprite,e.x,e.y,size,1,0,e.flash,alpha,e);const x=screenX(e.x),y=screenY(e.y)-size*1.5;if(e.elite){text(L(ENEMIES[e.id].name),x,y,13,'#dac283');text(L(MODIFIERS[e.mod1]),x,y+15,10,'#af9c7d');}if(e.hp<e.maxHp&&e.boss<0&&e.id!==99){const w=e.elite?50:30;rect(ctx,x-w/2,y+27,w,3,'#231c1b');rect(ctx,x-w/2,y+27,w*clamp(e.hp/e.maxHp,0,1),3,e.elite?'#b79551':'#8e4236');}}}
function drawAuras(){const p=run.player,x=screenX(p.x),y=screenY(p.y);if(p.shieldTime>0){ctx.save();ctx.globalAlpha=.5+.15*Math.sin(clock*4);ctx.strokeStyle='#d4cc9a';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(x,y-43,35,54,0,0,TAU);ctx.stroke();ctx.globalAlpha=.16;ctx.drawImage(glows.warm,x-65,y-115,130,150);ctx.restore();}if(p.buffPower>0){ctx.globalAlpha=.3;ctx.drawImage(glows.warm,x-80,y-100,160,160);ctx.globalAlpha=1;}}
function drawLighting(){const outdoor=run.sub===0||run.act===2&&run.sub===1,ambient=run.act===1&&run.sub===0?.25:outdoor?.43:run.sub===3?.7:.61;dc.globalCompositeOperation='source-over';dc.fillStyle=`rgba(5,7,9,${ambient})`;dc.fillRect(0,0,270,480);dc.globalCompositeOperation='destination-out';const p=run.player,x=screenX(p.x)/2,y=(screenY(p.y)-25)/2,r=(300+Math.sin(clock*8)*5)/2;dc.drawImage(glows.light,x-r,y-r,r*2,r*2);let lights=1,cap=quality==='low'?6:12;for(let i=0;i<props.count&&lights<cap;i++){const a=props.items[i];if(a.type!=='brazier'||!inView(a.x,a.y,160))continue;const sx=screenX(a.x)/2,sy=(screenY(a.y)-72)/2;dc.drawImage(glows.light,sx-58,sy-58,116,116);lights++;}for(let i=0;i<shots.count&&lights<cap;i++){const a=shots.items[i];if(!['fire','iceorb','spirit'].includes(a.kind)||!inView(a.x,a.y,90))continue;const sx=screenX(a.x)/2,sy=screenY(a.y)/2;dc.drawImage(glows.light,sx-38,sy-38,76,76);lights++;}dc.globalCompositeOperation='source-over';ctx.drawImage(dark,0,0,540,960);ctx.globalAlpha=run.act===1?.2:.5;ctx.drawImage(glows.warm,screenX(p.x)-220,screenY(p.y)-240,440,440);ctx.globalAlpha=1;}
function drawEffect(f){const x=screenX(f.x),y=screenY(f.y),t=1-f.life/f.max;if(!inView(f.x,f.y,f.r+150))return;ctx.save();ctx.strokeStyle=f.color;ctx.fillStyle=f.color;switch(f.kind){
 case 'hydra':{ctx.globalAlpha=Math.min(1,f.life);ellipse(ctx,x,y,25,10,'#38261f');for(let j=0;j<3;j++){const sx=x+(j-1)*16,sy=y-31-(j%2)*14+Math.sin(clock*4+j)*2;ctx.strokeStyle='#713b29';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(x+(j-1)*10,y);ctx.quadraticCurveTo(sx-10,sy+15,sx,sy);ctx.stroke();ctx.strokeStyle='#c27a40';ctx.lineWidth=3;ctx.stroke();poly(ctx,[sx-7,sy,sx-3,sy-9,sx+7,sy-7,sx+11,sy,sx+3,sy+4],graded(ctx,'#c7965b','#733e28'),'#382921');ellipse(ctx,sx+3,sy-4,1.5,1.5,'#f7cf7e');}break;}
 case 'sentry':ctx.drawImage(icons.w4,x-20,y-33,40,40);ctx.globalAlpha=.2+.1*Math.sin(clock*7);ctx.drawImage(glows.blue,x-40,y-55,80,80);break;
 case 'decoy':drawActor(selectedHero===5?'hero5':'hero1',f.x,f.y,70,1,0,0,.35+.1*Math.sin(clock*7));break;
 case 'prison':ctx.globalAlpha=Math.min(1,f.life);for(let j=0;j<18;j++){const a=j*TAU/18,xx=x+Math.cos(a)*f.r,yy=y+Math.sin(a)*f.r*.65;poly(ctx,[xx-4,yy,xx-3,yy-19,xx+1,yy-25,xx+5,yy-16,xx+4,yy],graded(ctx,'#d4d1b2','#737b70'),'#343c38');}break;
 case 'blizzard':ctx.globalAlpha=.16;ellipse(ctx,x,y,f.r,f.r*.72,'#84abc1');ctx.globalAlpha=.7;for(let j=0;j<15;j++){const xx=x+Math.sin(j*8.3)*f.r*.85,yy=y+Math.cos(j*6.1)*f.r*.58+(clock*80+j*23)%80-60;line(ctx,xx+9,yy-16,xx,yy,'#bcd9df',1.8);}break;
 case 'poisonWave':ctx.globalAlpha=(1-t)*.65;ctx.lineWidth=8*(1-t)+2;ctx.beginPath();ctx.ellipse(x,y,f.r*t,f.r*t*.78,0,0,TAU);ctx.stroke();for(let j=0;j<22;j++){const a=j*TAU/22+t;ellipse(ctx,x+Math.cos(a)*f.r*t,y+Math.sin(a)*f.r*t*.78,4,2,'#a0b76f');}break;
 case 'icefall':for(let j=0;j<4;j++){const xx=x+(j-1.5)*13,yy=y-(1-t)*100-j*9;poly(ctx,[xx-4,yy-17,xx+4,yy-8,xx+2,yy+5,xx-3,yy],graded(ctx,'#d7e9e5','#6995ab'),'#354953');}break;
 case 'holyStrike':ctx.globalAlpha=(1-t)*.9;ctx.lineWidth=12*(1-t)+1;line(ctx,x,y-320,x,y,'#f1e5b6',ctx.lineWidth);ctx.drawImage(glows.warm,x-f.r,y-f.r,f.r*2,f.r*2);ctx.globalAlpha=(1-t)*.8;ctx.beginPath();ctx.ellipse(x,y,f.r*t,f.r*t*.6,0,0,TAU);ctx.stroke();break;
 case 'lightningNova':for(let j=0;j<20;j++){const a=j*TAU/20,x1=x+Math.cos(a)*f.r*t,y1=y+Math.sin(a)*f.r*t*.8;ctx.globalAlpha=1-t;line(ctx,x+Math.cos(a)*f.r*t*.6,y+Math.sin(a)*f.r*t*.45,x1+Math.sin(j*5)*8,y1-4,'#d4ddeb',2);line(ctx,x1+Math.sin(j*5)*8,y1-4,x1,y1,'#91a8d1',2);}break;
 case 'warcry':case 'land':case 'leapDust':case 'corpseBlast':case 'blink':case 'kick':{ctx.globalAlpha=(1-t)*.75;ctx.lineWidth=f.kind==='land'?5:3;ctx.beginPath();ctx.ellipse(x,y,f.r*(.2+t*.8),f.r*(.2+t*.8)*.52,0,0,TAU);ctx.stroke();if(f.kind==='blink'){for(let j=0;j<9;j++){const a=j*TAU/9;line(ctx,x+Math.cos(a)*18,y-35+Math.sin(a)*40,x+Math.cos(a)*50*t,y-35+Math.sin(a)*80*t,f.color,2);}}else{for(let j=0;j<12;j++){const a=j*TAU/12;const xx=x+Math.cos(a)*f.r*t,yy=y+Math.sin(a)*f.r*t*.5;rect(ctx,xx,yy-Math.sin(t*Math.PI)*20,3,3,f.color);}}break;}
 default:ctx.restore();drawEffectV1(f);return;}
 ctx.restore();}
